{"command": "cd /workspace && python3 -c "
import numpy as np, wave
w=wave.open('work/iso.wav','rb'); sr=w.getframerate(); d=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).astype(float)
# sliding pitch
win=0.1; hop=0.1; W=int(win*sr)
out=[]
for st in range(0,len(d)-W,int(hop*sr)):
    seg=d[st:st+W]; seg=seg-np.mean(seg)
    F=np.abs(np.fft.rfft(seg)); fr=np.fft.rfftfreq(len(seg),1/sr)
    # restrict to musical range 100-1200
    m=(fr>100)&(fr<1200); 
    if m.sum()==0: out.append((st/sr,0)); continue
    pk=fr[m][np.argmax(F[m])]; out.append((st/sr,pk))
for t,p in out:
    if p>0: print(round(t,2),round(p,1))
" | head -80"}

